const c=require("crypto"),f=require("fs");
const liveness={};
const lines=f.readFileSync("data/stale-liveness.tsv","utf8").split("\n").slice(1).filter(Boolean);
for(const l of lines){const cols=l.split("\t"); liveness[cols[0]]={state:cols[1],why:cols[2],age:cols[3]};}
const batch=f.readFileSync("triage-batch/s4.txt","utf8").split("\n").filter(Boolean);
for(const line of batch){
  const url=line.split("|").pop().trim();
  const lv=liveness[url];
  const h=c.createHash("sha1").update(url).digest("hex").slice(0,16);
  console.log(JSON.stringify({num:line.match(/^(\d+)\./)[1], url, hash:h, liveness: lv||null}));
}
